diff --git a/apps/baremetal_bringup/main.c b/apps/baremetal_bringup/main.c
index 0def99a..ca14c48 100644
--- a/apps/baremetal_bringup/main.c
+++ b/apps/baremetal_bringup/main.c
@@ -594,6 +594,30 @@ static void h_sync(const uint32_t *a)
  * datasheet's characterisation condition; 0,0 is reset, which is what
  * this project has always run. See gen.c.
  */
+/*
+ * "=<gain>,<offset>U". Debug only, for the AFE's R1 question: sets the
+ * ADC's programmable gain (ADC_CGR, code 0..3 = gain 1,1,2,4 single
+ * ended) and offset (ADC_COR OFF bits) on every channel. With ANACH
+ * clear the converter applies channel 0's setting to all of them.
+ * acq_init() resets the ADC, so it re-applies these after the reset; they
+ * hold across captures until changed or a board reset. Not on the
+ * deployed path.
+ */
+static void h_pga(const uint32_t *a)
+{
+	uint32_t g = a[0] & 3u;
+	uint32_t off = a[1] ? 1u : 0u;
+
+	acq_cgr = g * 0x55555555u;
+	acq_cor = off ? 0xFFFFu : 0u;
+	ADC->ADC_CGR = acq_cgr;
+	ADC->ADC_COR = acq_cor;
+	con_str("# adc pga: ");
+	con_kv_u32("cgr", ADC->ADC_CGR); con_ch(' ');
+	con_kv_u32("cor", ADC->ADC_COR); con_nl();
+	uart_flush();
+}
+
 static void h_ibctl(const uint32_t *a)
 {
 	gen_set_ibctl(a[0], a[1]);
@@ -712,7 +736,7 @@ const console_binding_t console_bindings[] = {

 	{ 'Q', h_profile },     { 'l', h_load },        { 'S', h_stall },
 	{ 'K', h_mimic_gap },   { 'Z', h_detach },      { 'z', h_reset },
-	{ 'q', h_fws },         { 'y', h_time },
+	{ 'q', h_fws },         { 'y', h_time },        { 'U', h_pga },

 	{ 0, 0 },
 };
diff --git a/drivers/acq.c b/drivers/acq.c
index 03e28b4..c0a55d3 100644
--- a/drivers/acq.c
+++ b/drivers/acq.c
@@ -123,6 +123,9 @@ uint32_t acq_mr(void)
 	return ADC->ADC_MR;
 }

+uint32_t acq_cgr;
+uint32_t acq_cor;
+
 void acq_init(void)
 {
 	PMC->PMC_PCER1 = (1u << (ID_ADC - 32));
@@ -141,6 +144,11 @@ void acq_init(void)
 	ADC->ADC_EMR = ADC_EMR_TAG;
 	ADC->ADC_CHDR = 0xffffu;
 	ADC->ADC_CHER = (1u << ADC_CH_A0) | (1u << ADC_CH_A1);
+	/* Debug only (the U command): the SWRST above clears gain and offset,
+	 * so the requested values are applied after it. Zero is the reset
+	 * default, gain 1 with no offset. */
+	ADC->ADC_CGR = acq_cgr;
+	ADC->ADC_COR = acq_cor;
 }

 bool acq_start(uint32_t trigger_hz, unsigned n_channels)
diff --git a/drivers/acq.h b/drivers/acq.h
index 4629fce..613faf4 100644
--- a/drivers/acq.h
+++ b/drivers/acq.h
@@ -114,6 +114,9 @@ extern acq_slot_t acq_slot[ACQ_NBUF];
 extern uint8_t acq_tracktim;
 extern uint8_t acq_settling;
 void acq_set_timing(uint32_t tracktim, uint32_t settling);
+/* Debug only: ADC_CGR / ADC_COR applied by acq_init() after its reset. */
+extern uint32_t acq_cgr;
+extern uint32_t acq_cor;

 /* Which channel joins A0 in a two-channel capture. See acq.c. */
 extern uint8_t acq_pair_second;
